-- ThriftRadarFL migrations 0002–0006 (publish flag, sale tags, audit log, editable deal rules, submissions, contact messages, venue source_url/org_key)
-- Safe to run more than once. Paste into Supabase → SQL Editor → Run.
BEGIN;
ALTER TABLE sales ADD COLUMN IF NOT EXISTS published boolean DEFAULT true NOT NULL;
ALTER TABLE sales ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE sales ADD COLUMN IF NOT EXISTS tags text[]; -- 0003
ALTER TABLE venues ADD COLUMN IF NOT EXISTS source_url text; -- 0005
ALTER TABLE venues ADD COLUMN IF NOT EXISTS org_key text; -- 0005
CREATE TABLE IF NOT EXISTS color_tag_reports (id text PRIMARY KEY, venue text NOT NULL, color text NOT NULL, discount_pct integer, note text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', week_of text NOT NULL, expires_on text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); -- 0006
CREATE INDEX IF NOT EXISTS color_tag_reports_expires_idx ON color_tag_reports (expires_on); -- 0006
ALTER TABLE deal_rules ADD COLUMN IF NOT EXISTS rule_key text;
ALTER TABLE deal_rules ADD COLUMN IF NOT EXISTS label text;
ALTER TABLE deal_rules ADD COLUMN IF NOT EXISTS verified boolean DEFAULT false NOT NULL;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'deal_rules_rule_key_unique') THEN
    ALTER TABLE deal_rules ADD CONSTRAINT deal_rules_rule_key_unique UNIQUE (rule_key);
  END IF;
END $$;
CREATE TABLE IF NOT EXISTS submissions (
  id text PRIMARY KEY NOT NULL, email text NOT NULL, sale jsonb NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages (
  id text PRIMARY KEY NOT NULL, name text NOT NULL, email text NOT NULL, message text NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
-- Private tables: no anon/authenticated access via the Supabase Data API (the app connects as the postgres role).
CREATE TABLE IF NOT EXISTS audit_log ( -- 0004
  id serial PRIMARY KEY NOT NULL, at timestamptz DEFAULT now() NOT NULL, action text NOT NULL, target text, detail text);
ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE submissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE contact_messages ENABLE ROW LEVEL SECURITY;

-- Seed/refresh venues (new stores added 2026-11-02 with sources in notes)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, address = EXCLUDED.address, city = EXCLUDED.city, zip = EXCLUDED.zip, lat = EXCLUDED.lat, lng = EXCLUDED.lng, phone = EXCLUDED.phone, hours_json = EXCLUDED.hours_json, notes = EXCLUDED.notes, source_url = EXCLUDED.source_url, org_key = EXCLUDED.org_key;

-- Remove stores dropped from the seed (not on the official Goodwill CFL list); its deal rules cascade
DELETE FROM venues WHERE slug IN ('goodwill-daytona-isb', 'st-vincent-de-paul-thrift-store-longwood', 'habitat-seminole-apopka-restore-casselberry');
-- Legacy rules inserted by scripts/seed.ts before rule_key existed would duplicate the keyed rows below
DELETE FROM deal_rules WHERE rule_key IS NULL;

-- Seed deal rules (upsert by rule_key)
SELECT v.rule_key, ve.id, v.kind::deal_kind, v.day, v.t::time, v.color, v.pct, v.label, v.label, v.verified
FROM (VALUES
  ('goodwill-port-orange-0-color-of-the-week-50-off-color-changes-sundays-posted-in-store', 'goodwill-port-orange', 'color_tag', 0, NULL, 'bg-teal', 50, 'Color of the Week 50% off (color changes Sundays, posted in store)', true),
  ('goodwill-port-orange-1-seniors-55-discount-ask-in-store-for-amount', 'goodwill-port-orange', 'senior_day', 1, NULL, 'bg-gray-700', NULL, 'Seniors 55+ discount (ask in store for amount)', true),
  ('goodwill-port-orange-3-military-10-off', 'goodwill-port-orange', 'senior_day', 3, NULL, 'bg-gray-700', 10, 'Military 10% off', true),
  ('goodwill-port-orange-2-fresh-housewares-floor-am', 'goodwill-port-orange', 'restock', 2, '09:00', 'bg-royal', NULL, 'Fresh housewares floor (AM)', false),
  ('goodwill-pine-hills-outlet-1-heavy-bin-restock-am', 'goodwill-pine-hills-outlet', 'restock', 1, '08:00', 'bg-royal', NULL, 'Heavy bin restock (AM)', false),
  ('goodwill-pine-hills-outlet-4-bins-lb-discount-day', 'goodwill-pine-hills-outlet', 'dollar_day', 4, NULL, 'bg-coral', NULL, 'Bins $/lb discount day', false),
  ('goodwill-pine-hills-outlet-6-saturday-bin-rotations-hourly', 'goodwill-pine-hills-outlet', 'bins_rotation', 6, NULL, 'bg-royal', NULL, 'Saturday bin rotations hourly', false),
  ('goodwill-taft-outlet-2-heavy-bin-restock-am', 'goodwill-taft-outlet', 'restock', 2, '08:00', 'bg-royal', NULL, 'Heavy bin restock (AM)', false),
  ('goodwill-taft-outlet-4-select-bins-1-items', 'goodwill-taft-outlet', 'dollar_day', 4, NULL, 'bg-coral', NULL, 'Select bins $1 items', false),
  ('goodwill-taft-outlet-6-furniture-rotation', 'goodwill-taft-outlet', 'bins_rotation', 6, '10:00', 'bg-royal', NULL, 'Furniture rotation', false),
  ('berners-auction-deland-2-preview-day', 'berners-auction-deland', 'restock', 2, NULL, 'bg-gray-700', NULL, 'Preview day', false),
  ('berners-auction-deland-3-weekly-auction', 'berners-auction-deland', 'restock', 3, '18:30', 'bg-royal', NULL, 'Weekly auction', true),
  ('salvation-army-w-colonial-orlando-3-customer-appreciation-day-50-off-all-tag-colors-but-one-yelp', 'salvation-army-w-colonial-orlando', 'half_off', 3, NULL, 'bg-coral', 50, 'Customer Appreciation Day: 50% off all tag colors but one (Yelp)', false),
  ('omg-thrift-1-color-of-the-week-half-price-changes-mondays-per-thriftstores-net', 'omg-thrift', 'color_tag', 1, NULL, 'bg-teal', 50, 'Color of the Week half price (changes Mondays, per thriftstores.net)', false),
  ('the-hope-chest-6-1-clothing-non-boutique-per-mylocalnooks-com', 'the-hope-chest', 'dollar_day', 6, NULL, 'bg-coral', NULL, '$1 clothing, non-boutique (per mylocalnooks.com)', false),
  ('city-thrift-edgewater-2-seniors-30-off-per-uncoveringflorida-com', 'city-thrift-edgewater', 'senior_day', 2, NULL, 'bg-gray-700', 30, 'Seniors 30% off (per uncoveringflorida.com)', false),
  ('city-thrift-edgewater-3-military-discount-per-uncoveringflorida-com', 'city-thrift-edgewater', 'senior_day', 3, NULL, 'bg-gray-700', NULL, 'Military discount (per uncoveringflorida.com)', false)
) AS v(rule_key, venue, kind, day, t, color, pct, label, verified)
JOIN venues ve ON ve.slug = v.venue
ON CONFLICT (rule_key) DO UPDATE SET kind = EXCLUDED.kind, day_of_week = EXCLUDED.day_of_week, start_time = EXCLUDED.start_time, color = EXCLUDED.color,
  discount_pct = EXCLUDED.discount_pct, label = EXCLUDED.label, description = EXCLUDED.description, verified = EXCLUDED.verified;

